def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue

                # Extend the matching diagonal outward from both ends.
                for rr, cc, sr, sc in ((r - dr, c - dc, -dr, -dc),
                                       (r2 + dr, c2 + dc, dr, dc)):
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc

    return out
